   310	    DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   311	       "check_range [%p..%p] (%d bytes) in [%p..%p] -> %s",
   312	       p, p + len, len,
   313	       this->start, this->end,
