   387	    Type *t = CastP<Type> (const_cast<char *> (start));
   388	
   389	    sane = t->sanitize (this);
   390	    if (sane)
   391	    {
   392	      if (edit_count)
   393	      {
   394	        DEBUG_MSG_FUNC (SANITIZE, start, "passed first round with %d edits; going for second round", edit_count);
   395	
   396	        /* sanitize again to ensure no toe-stepping */
   397	        edit_count = 0;
   398	        sane = t->sanitize (this);
   399	        if (edit_count) {
   400	          DEBUG_MSG_FUNC (SANITIZE, start, "requested %d edits in second round; FAILLING", edit_count);
